style.css:
@-moz-document url-prefix("https://reddit.com"), url-prefix("https://www.reddit.com") {
@media (min-width: 1200px) {
    .m\:w-\[1120px\] {
      width: 100%;
    }
  }

  .flex-grid--main-container-card.right-sidebar-m,
  .flex-grid--main-container-card.right-sidebar-s,
  .flex-grid--main-container-card.right-sidebar-xs {
    max-width: unset;
  }

  div[slot="post-media-container"] {
    max-width: 1000px;
  }

  shreddit-player-2 {
    max-width: 1000px;
    aspect-ratio: 16/9;
  }

  .grid-container:not(.grid-full) .subgrid-container {
    max-width: unset !important;
    width: 100% !important;
  }

  .flex-grid--main-container-card.right-sidebar-m, .flex-grid--main-container-card.right-sidebar-s, .flex-grid--main-container-card.right-sidebar-xs {
    max-width: 73vw !important;
  }
}
